  const [key, setKey] = useState(apiKey), [editing, setEditing] = useState(false), [state, setState] = useState<Connection>(connection);
  const [copyState, setCopyState] = useState<"idle" | "copied" | "error">("idle");
  const buttons = useRef<(HTMLButtonElement | null)[]>([]), keyInput = useRef<HTMLInputElement>(null);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const clearTimers = () => { timers.current.forEach(clearTimeout); timers.current = []; };
  const transition = reduced ? { duration: 0 } : { type: "spring" as const, duration: .4, bounce: .12 };
  const fade = { duration: reduced ? 0 : .16 };
  useEffect(() => { setChosen(clients.some(item => item.id === client) ? client : "cursor"); setMode(transport); setWhere(scope); setKey(apiKey); setState(connection); setCopyState("idle"); setEditing(false); clearTimers(); }, [client, transport, scope, apiKey, connection, replayKey]);
