  useEffect(() => { if (editing) { keyInput.current?.focus(); keyInput.current?.select(); } }, [editing]);
  const current = clients.find(item => item.id === chosen)!;
  const local = mode === "local", globalOnly = chosen === "claude" || chosen === "windsurf", effectiveScope = globalOnly ? "global" : where;
