  const config = chosen === "zed" ? { context_servers: { [server]: local ? { command: { path: "npx", args: localArgs, env: { [variable]: secret } } } : { url } } } : { mcpServers: { [server]: local ? { command: "npx", args: localArgs, env: { [variable]: secret } } : { [chosen === "windsurf" ? "serverUrl" : "url"]: url } } };
  const commandText = local ? `claude mcp add --scope ${effectiveScope === "project" ? "project" : "user"} ${shell(server)} --env ${shell(variable + "=" + secret)} -- npx ${localArgs.map(shell).join(" ")}` : `claude mcp add --transport http --scope ${effectiveScope === "project" ? "project" : "user"} ${shell(server)} ${shell(url)}`;
  const copiedText = command ? commandText : steps ? `Settings › Connectors\nAdd custom connector\nName: ${serviceName}\nURL: ${url}` : formatConfig(config);
  const path = command ? "Terminal" : steps ? "Claude · Settings" : chosen === "cursor" ? effectiveScope === "project" ? ".cursor/mcp.json" : "~/.cursor/mcp.json" : chosen === "claude" ? "~/Library/Application Support/Claude/claude_desktop_config.json" : chosen === "windsurf" ? "~/.codeium/windsurf/mcp_config.json" : ".zed/settings.json";
  const resetCopy = () => { clearTimers(); setCopyState("idle"); if (state === "waiting") setState("idle"); };
  const selectClient = (next: Client) => { resetCopy(); setChosen(next); setEditing(false); };
  const changeMode = (next: Transport) => { resetCopy(); setMode(next); setEditing(false); };
  const updateKey = (value: string) => { setKey(value); onApiKeyChange?.(value); };
