        <h3 className="nmi-title">Add {serviceName} to <AnimatePresence mode="popLayout" initial={false}><motion.span key={chosen} style={{ display: "inline-block" }} initial={{ opacity: 0, filter: "blur(3px)", transform: "translateY(4px)" }} animate={{ opacity: 1, filter: "blur(0px)", transform: "translateY(0px)" }} exit={{ opacity: 0, filter: "blur(3px)", transform: "translateY(-4px)" }} transition={fade}>{current.name}</motion.span></AnimatePresence></h3>
